"use client";

import { useEffect, useState } from "react";
import { MapPin, Filter, Briefcase } from "lucide-react";
import { supabase } from "@/lib/supabase";
import { useUserStore } from "@/store/useUserStore";
import { AnimatedList, AnimatedListItem, AnimatedButton, FadeIn } from "@/components/ui/animations";
import { motion } from "framer-motion";
import EmptyState from "@/components/shared/EmptyState";

type TabKey = "pending" | "accepted" | "completed";

const STATUS_CONFIG = {
    pending: { color: "#d97706", bg: "#fffbeb", label: "Pending" },
    accepted: { color: "#0e9f6e", bg: "#ecfdf5", label: "Accepted" },
    completed: { color: "#6b7280", bg: "#f3f4f6", label: "Completed" },
};

interface ApplicationRecord {
    id: string;
    status: string;
    bid_amount: number;
    created_at: string;
    job_title: string;
    job_location: string;
    job_category: string;
    job_daily_rate: number;
    job_duration: string;
    employer_name: string;
    employer_init: string;
    employer_color: string;
}

export default function ApplicationsPage() {
    const { generalProfile } = useUserStore();
    const [tab, setTab] = useState<TabKey>("pending");
    const [applications, setApplications] = useState<ApplicationRecord[]>([]);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        async function fetchApplications() {
            const userId = generalProfile?.id;
            if (!userId) { setLoading(false); return; }
            setLoading(true);

            const { data } = await supabase
                .from("applications")
                .select("id, status, bid_amount, created_at, job_id, employer_id")
                .eq("worker_id", userId)
                .order("created_at", { ascending: false });

            if (!data || data.length === 0) { setLoading(false); return; }

            // Fetch job details
            const jobIds = [...new Set(data.map(a => a.job_id))];
            const { data: jobs } = await supabase
                .from("jobs")
                .select("id, title, location, category, daily_rate, duration")
                .in("id", jobIds);
            const jobMap = new Map((jobs ?? []).map(j => [j.id, j]));

            // Fetch employer details
            const empIds = [...new Set(data.map(a => a.employer_id))];
            const { data: employers } = await supabase
                .from("employer_profiles")
                .select("id, company_name")
                .in("id", empIds);
            const empMap = new Map((employers ?? []).map(e => [e.id, e]));

            const colors = ["#0a2540", "#1a3a5c", "#059669", "#7c3aed", "#d97706"];
            const mapped: ApplicationRecord[] = data.map((a, i) => {
                const job = jobMap.get(a.job_id);
                const emp = empMap.get(a.employer_id);
                return {
                    id: a.id,
                    status: a.status,
                    bid_amount: a.bid_amount,
                    created_at: a.created_at,
                    job_title: job?.title ?? "Job",
                    job_location: job?.location ?? "",
                    job_category: job?.category ?? "",
                    job_daily_rate: job?.daily_rate ?? 0,
                    job_duration: job?.duration ?? "",
                    employer_name: emp?.company_name ?? "Employer",
                    employer_init: (emp?.company_name ?? "E")[0],
                    employer_color: colors[i % colors.length],
                };
            });
            setApplications(mapped);
            setLoading(false);
        }
        fetchApplications();
    }, [generalProfile?.id]);

    const tabs: { key: TabKey; label: string }[] = [
        { key: "pending", label: "Pending" },
        { key: "accepted", label: "Accepted" },
        { key: "completed", label: "Completed" },
    ];

    const filteredItems = applications.filter(a => a.status === tab);

    return (
        <div className="space-y-5">
            {/* Header */}
            <FadeIn>
                <h1 className="font-outfit font-bold" style={{ fontSize: 24, color: "#111827" }}>My Applications</h1>
            </FadeIn>

            {/* Tabs */}
            <FadeIn delay={0.1}>
                <div className="flex gap-2">
                    {tabs.map(t => {
                        const count = applications.filter(a => a.status === t.key).length;
                        return (
                            <AnimatedButton key={t.key} onClick={() => setTab(t.key)}
                                tapScale={0.93} hoverScale={1.05}
                                className="px-4 py-2 rounded-xl font-dmsans font-semibold transition-all"
                                style={{
                                    fontSize: 13,
                                    background: tab === t.key ? "#0a2540" : "white",
                                    color: tab === t.key ? "white" : "#6b7280",
                                    border: tab === t.key ? "none" : "1px solid #e5e7eb",
                                }}>
                                {t.label} {count > 0 && `(${count})`}
                            </AnimatedButton>
                        );
                    })}
                </div>
            </FadeIn>

            {/* Loading */}
            {loading && (
                <div className="bg-white rounded-2xl border overflow-hidden p-5 space-y-4" style={{ borderColor: "#e5e7eb" }}>
                    {[1, 2, 3].map(i => (
                        <div key={i} className="animate-pulse flex items-center gap-3">
                            <div className="w-9 h-9 bg-gray-200 rounded-xl" />
                            <div className="flex-1 space-y-2">
                                <div className="h-4 bg-gray-200 rounded w-40" />
                                <div className="h-3 bg-gray-100 rounded w-24" />
                            </div>
                            <div className="h-6 bg-gray-100 rounded-full w-16" />
                        </div>
                    ))}
                </div>
            )}

            {/* Empty State */}
            {!loading && filteredItems.length === 0 && (
                <EmptyState
                    icon={<Briefcase className="w-8 h-8" />}
                    title={`No ${tab} applications`}
                    subtitle={tab === "pending" ? "Apply to jobs and track them here." : `No ${tab} applications yet.`}
                />
            )}

            {/* Table */}
            {!loading && filteredItems.length > 0 && (
                <FadeIn delay={0.15}>
                    <div className="bg-white rounded-2xl border overflow-hidden" style={{ borderColor: "#e5e7eb" }}>
                        <div className="grid px-5 py-3" style={{ gridTemplateColumns: "2fr 1.5fr 1fr 1fr 1fr", background: "#f8fafc", borderBottom: "1px solid #f3f4f6" }}>
                            {["Company", "Role", "Location", "Rate", "Status"].map((h) => (
                                <p key={h} className="font-dmsans font-semibold" style={{ fontSize: 12, color: "#9ca3af", textTransform: "uppercase" }}>{h}</p>
                            ))}
                        </div>

                        <AnimatedList key={tab}>
                            {filteredItems.map((item, i) => {
                                const config = STATUS_CONFIG[item.status as TabKey] ?? STATUS_CONFIG.pending;
                                return (
                                    <AnimatedListItem key={item.id}>
                                        <motion.div
                                            className="grid items-center px-5 py-4 cursor-pointer transition-colors"
                                            style={{ gridTemplateColumns: "2fr 1.5fr 1fr 1fr 1fr", borderBottom: i < filteredItems.length - 1 ? "1px solid #f9fafb" : "none" }}
                                            whileHover={{ backgroundColor: "rgba(249,250,251,1)" }}
                                        >
                                            <div className="flex items-center gap-3">
                                                <div className="w-9 h-9 rounded-xl flex items-center justify-center font-outfit font-bold text-white text-sm shrink-0"
                                                    style={{ background: item.employer_color }}>{item.employer_init}</div>
                                                <p className="font-dmsans font-bold" style={{ fontSize: 14, color: "#111827" }}>{item.employer_name}</p>
                                            </div>
                                            <p style={{ fontSize: 14, color: "#374151" }}>{item.job_title}</p>
                                            <div className="flex items-center gap-1">
                                                <MapPin className="w-3.5 h-3.5 shrink-0" style={{ color: "#9ca3af" }} />
                                                <p style={{ fontSize: 13, color: "#6b7280" }}>{item.job_location || "—"}</p>
                                            </div>
                                            <p className="font-outfit font-bold" style={{ fontSize: 14, color: "#0e9f6e" }}>
                                                ₹{item.bid_amount?.toLocaleString("en-IN") || item.job_daily_rate?.toLocaleString("en-IN")}
                                            </p>
                                            <span className="px-2.5 py-1 rounded-full font-dmsans font-semibold w-fit"
                                                style={{ fontSize: 11, background: config.bg, color: config.color }}>
                                                {config.label}
                                            </span>
                                        </motion.div>
                                    </AnimatedListItem>
                                );
                            })}
                        </AnimatedList>
                    </div>
                </FadeIn>
            )}
        </div>
    );
}
